<?php declare(strict_types=1);require_once __DIR__.'/../auth/seguridad.php';require_once __DIR__.'/../conexion_postgres.php';$admin=exigirAdministrador(['POST']);$d=json_decode(file_get_contents('php://input'),true);$id=filter_var($d['id']??null,FILTER_VALIDATE_INT);if($id===false||$id<1)responderJson(['error'=>'ID no válido.'],400);$n=trim((string)($d['name']??''));$e=strtolower(trim((string)($d['email']??'')));$r=$d['role']??'user';if($n===''||!filter_var($e,FILTER_VALIDATE_EMAIL)||!in_array($r,['user','admin'],true))responderJson(['error'=>'Datos no válidos.'],400);if($id===$admin&&$r!=='admin')responderJson(['error'=>'No puedes retirarte el rol administrador.'],400);try{$q=retornarConexionPostgres()->prepare('update public.users set name=:n,email=:e,role=:r,password=coalesce(nullif(:p,\'\'),password) where id=:id returning id,name,email,role,created_at,updated_at');$q->execute([':n'=>$n,':e'=>$e,':r'=>$r,':p'=>isset($d['password'])&&$d['password']!==''?password_hash($d['password'],PASSWORD_DEFAULT):'',':id'=>$id]);$u=$q->fetch();if(!$u)responderJson(['error'=>'Usuario no encontrado.'],404);responderJson(['result'=>'OK','user'=>$u]);}catch(PDOException $x){responderJson(['error'=>'No se pudo actualizar el usuario.'],500);}
